export interface SiteNavLink {
  href: string
  label: string
  external?: boolean
}

export type SiteNavItem = SiteNavLink | { label: string; items: SiteNavLink[] }

export function isSiteNavGroup(item: SiteNavItem): item is { label: string; items: SiteNavLink[] } {
  return "items" in item
}

/**
 * True when `pathname` represents the same page as `href`, including nested
 * routes (e.g. `/blog/some-post` is active for a `/blog` link). The root path
 * is matched exactly so it doesn't shadow every route.
 */
export function isActivePath(pathname: string, href: string): boolean {
  if (href === "/") return pathname === "/"
  return pathname === href || pathname.startsWith(`${href}/`)
}

