/* Skip link — replaces the artboards' onFocus/onBlur handlers with CSS. */
.skip-link:focus{left:8px!important;top:8px!important;z-index:100}

/* ══════════════════════════════════════════════════════════════════════════
   Shared page furniture

   The artboard pages carry their styling inline, which is fine while every
   pattern appears once. These repeat on every page of the build sequence, so
   they are classes: a kicker, a spec list, and the hatched "to be issued"
   fill. Same values the inline versions use, so the two never disagree.
   ══════════════════════════════════════════════════════════════════════ */

.kicker{margin:0 0 10px;font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.kicker-a{color:var(--color-accent-700)}
.mono{font-family:var(--font-mono)}
.hatch{background-image:repeating-linear-gradient(135deg,var(--rule) 0 1px,transparent 1px 9px)}

.spec{margin:0;display:grid;grid-template-columns:auto minmax(0,1fr);gap:0 clamp(14px,2vw,24px);font-size:14.5px}
.spec dt{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);padding:9px 0;border-bottom:1px solid var(--rule)}
.spec dd{margin:0;padding:9px 0;border-bottom:1px solid var(--rule)}
.spec dt:last-of-type,.spec dd:last-child{border-bottom:0}
/* File paths and part numbers are unbreakable strings; let them break rather
   than push the page sideways. Under ~560px the pair stacks, because a mono
   path and a label cannot share 500px of phone. */
.spec dd{overflow-wrap:anywhere}
@media (max-width:560px){
  .spec{grid-template-columns:minmax(0,1fr)}
  .spec dt{padding:9px 0 0;border-bottom:0}
  .spec dd{padding-top:2px}
}

/* ══════════════════════════════════════════════════════════════════════════
   The electronics path switch

   Two ways to build Marvin's electronics — soldered from modules, or on the
   PCBs that are specified but not yet designed. They share every mechanical
   step and differ in five, so the assembly sequence is written once and
   filtered, rather than printed twice.

   No JavaScript: a radio group plus :has(). That matters here more than
   usual, because the thing being hidden is instructions — with a scripted
   filter, a reader whose script failed would be shown a sequence with holes
   in it and no way to tell. Numbering comes from a CSS counter, so the
   visible steps always read 01..n whichever path is selected. The default
   (and the state a browser without :has() is stuck in) is the soldered path,
   which is the only one anybody can build today.
   ══════════════════════════════════════════════════════════════════════ */

.paths:has(#mv-path-solder:checked) [data-when="pcb"]{display:none}
.paths:has(#mv-path-pcb:checked) [data-when="solder"]{display:none}

.pathsw{margin:0;padding:0;border:0;display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.pathsw legend{float:left;width:100%;margin:0 0 8px;padding:0;font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.pathsw input{position:absolute;opacity:0;width:0;height:0;pointer-events:none}
.pathsw label{cursor:pointer;display:inline-flex;align-items:baseline;gap:8px;padding:9px 14px;border:1px solid var(--rule-ink);font-family:var(--font-heading);font-weight:600;font-size:17px;letter-spacing:.01em;line-height:1.1}
.pathsw label .n{font-family:var(--font-mono);font-weight:400;font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.pathsw label:hover{background:color-mix(in srgb,var(--color-text) 6%,transparent)}
.pathsw input:checked + label{background:var(--color-accent);border-color:var(--color-accent);color:var(--color-bg)}
.pathsw input:checked + label .n{color:color-mix(in srgb,var(--color-bg) 80%,transparent)}
.pathsw input:focus-visible + label{outline:2px solid var(--color-accent);outline-offset:2px}

.steps{counter-reset:mv-step;list-style:none;margin:0;padding:0;border-bottom:1px solid var(--rule)}
.steps > li{counter-increment:mv-step;display:grid;grid-template-columns:clamp(46px,6vw,74px) minmax(0,1fr);gap:0 clamp(14px,2.4vw,28px);padding:clamp(16px,2.2vw,22px) 0;border-top:1px solid var(--rule)}
.steps > li > .n::before{content:counter(mv-step,decimal-leading-zero)}
.steps > li > .n{font-family:var(--font-heading);font-weight:600;font-size:clamp(30px,4.4vw,46px);line-height:.86;letter-spacing:-.02em;font-variant-numeric:tabular-nums;color:var(--color-accent-700)}
.steps h3{margin:0 0 6px;font-size:clamp(18px,2vw,21px);line-height:1.18;letter-spacing:-.005em}
.steps p{margin:0;max-width:64ch;font-size:14.5px;color:var(--muted)}
.steps p + p{margin-top:8px}
.steps > li[data-when="solder"] > .n,.steps > li[data-when="pcb"] > .n{color:var(--color-accent)}

/* ══════════════════════════════════════════════════════════════════════════
