export function SystemStatus({
  className,
  pulse = false,
  style,
  textColorClassName,
  textSize = "text-sm",
}: {
  className?: string
  pulse?: boolean
  style?: CSSProperties
  textColorClassName?: string
  textSize?: string
}) {
  const [data, setData] = useState<StatusSummary | null>(null)
  const [isError, setIsError] = useState(false)

  useEffect(() => {
    let active = true
    async function poll() {
      try {
        const res = await fetch(STATUS_API_URL)
        if (!res.ok) throw new Error(`Status API ${res.status}`)
        const json = (await res.json()) as StatusSummary
        if (active) {
          setData(json)
          setIsError(false)
        }
      } catch {
        if (active) setIsError(true)
      }
    }
    poll()
    const id = setInterval(poll, 60_000)
    return () => {
      active = false
      clearInterval(id)
    }
  }, [])

  if (!data && !isError) return null

  const status =
    isError || !data
      ? "unknown"
      : (data.ongoing_incidents?.length ?? 0) > 0
        ? "degraded"
        : (data.in_progress_maintenances?.length ?? 0) > 0
          ? "maintenance"
          : "operational"

