const { chromium } = require('/Users/thomi/Projects/entire.io/node_modules/.pnpm/node_modules/playwright');
(async()=>{
const browser=await chromium.launch({headless:true});
const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
for(const width of [1440,390]){
 await page.setViewportSize({width,height:1000});
 for(const file of ['index','build','electronics','drive','reference','contribute']){
  await page.goto(`http://127.0.0.1:4173/${file}.html`);await page.evaluate(()=>document.fonts.ready);
  const result=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth,wide:[...document.querySelectorAll('main *')].filter(e=>e.getBoundingClientRect().right>innerWidth+2).slice(0,5).map(e=>e.tagName+'.'+e.className),font:getComputedStyle(document.querySelector('h1')).fontFamily,logo:document.querySelector('.entire-home').href,footer:document.querySelectorAll('.entire-footer__columns li').length}));
  console.log(width,file,JSON.stringify(result));
  if(file==='index') await page.screenshot({path:`/tmp/marvin-${width}.png`,fullPage:false});
 }
}
await page.goto('http://127.0.0.1:4173/index.html');await page.locator('.theme-toggle').click();console.log('theme',await page.locator('html').getAttribute('data-theme'));await page.screenshot({path:'/tmp/marvin-dark.png'});
console.log('errors',errors);await browser.close();
