  return <div className={classes}>{children}</div>
}
import { useRef } from "react"

import { SiteSection } from "../site/SiteSection"
import {
  COMPETITOR_A_STEPS,
  COMPETITOR_B_STEPS,
  COMPETITOR_C_STEPS,
  COUNT_UP_STEPS,
} from "./networkSpeedData"
import { NetworkSpeedGauge } from "./NetworkSpeedGauge"
import { NetworkSpeedRollingCounter } from "./NetworkSpeedRollingCounter"
import { useNetworkSpeedTimeline } from "./useNetworkSpeedTimeline"

interface MetricProps {
  isActive: boolean
  isPaused: boolean
  isVisible: boolean
  label: string
  values: readonly number[]
  value: number
  variant?: "competitor" | "primary"
}

function SpeedMetric({
  isActive,
  isPaused,
  isVisible,
  label,
  values,
  value,
  variant = "competitor",
}: MetricProps) {
  const isCompetitorA = label === "GitHub"
  const isCompetitorC = label === "Cursor"
  const isPrimary = variant === "primary"
  const displayedValue = isVisible ? value : 0
  const counter = (
    <NetworkSpeedRollingCounter
      ariaLabel={isPrimary ? `${displayedValue} pushes per second` : `${displayedValue} ${label}`}
      className={isCompetitorA ? "is-competitor-a" : isCompetitorC ? "cursor-wait" : undefined}
      digitCount={isPrimary ? undefined : String(value).length}
      isActive={isActive}
      isPaused={isPaused}
      value={displayedValue}
      values={values}
      variant={variant}
    />
  )
  const metricLabel = (
    <p
      className={`font-sans text-xs font-semibold text-muted ${isPrimary ? "mt-2" : "mt-1"} ${isCompetitorC ? "cursor-help" : ""}`}
    >
      {label}
    </p>
  )

  return (
    <NetworkSpeedGauge
      isActive={isActive}
      isPaused={isPaused}
      isVisible={isVisible}
      value={value}
      variant={variant}
    >
      {counter}
      {metricLabel}
    </NetworkSpeedGauge>
  )
}

interface CompetitorConfig {
  label: string
  value: number
  values: readonly number[]
}

function CompetitorCell({
  competitor,
  isActive,
  isPaused,
  isVisible,
}: {
  competitor: CompetitorConfig
  isActive: boolean
  isPaused: boolean
  isVisible: boolean
}) {
  return (
    <div className="relative flex min-h-0 items-center justify-center">
      <SpeedMetric
        isActive={isActive}
        isPaused={isPaused}
        isVisible={isVisible}
        label={competitor.label}
        values={competitor.values}
        value={competitor.value}
      />
    </div>
  )
}
