import { useEffect, useRef, type RefObject } from "react"

const defaultSeed = 0x9e3779b9
const revealTransitionMs = 220
const mountWarmupFrames = 6

// Pulsing ripple tuning (see `rippleActive`). Ring crests expand outward from
// the ripple origin, fading out past `rippleMaxRadius`.
const rippleFadeMs = 260
const rippleSpeed = 130 // px/second that ring crests travel outward
const ripplePeriod = 130 // px between successive ring crests
const rippleBandWidth = 46 // px thickness of each crest
const rippleMaxRadius = 560 // px beyond which ripples dissipate
const defaultRippleColor = { r: 99, g: 102, b: 241 } // indigo-500
const defaultRippleColorAlt = { r: 165, g: 180, b: 252 } // indigo-300

interface DotGridBackgroundProps {
  className?: string
  gap?: number
  dotSize?: number
  sizeRange?: number
  opacityRange?: number
  revealRadius?: number
  seed?: number
  /** While true, ring crests pulse outward from `rippleOrigin` in `rippleColor`. */
  rippleActive?: boolean
  /** Element whose center the ripples emanate from (defaults to canvas center). */
  rippleOrigin?: RefObject<HTMLElement | null>
  /** RGB color of the ripple crests (defaults to indigo-500). */
  rippleColor?: { r: number; g: number; b: number }
  /** Alternate crest color; successive rings alternate between the two (defaults to indigo-300). */
  rippleColorAlt?: { r: number; g: number; b: number }
}

function mulberry32(seed: number) {
  return function random() {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0

    let value = Math.imul(seed ^ (seed >>> 15), 1 | seed)

    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value

    return ((value ^ (value >>> 14)) >>> 0) / 4294967296
  }
}

function getDotColor() {
  const isDark =
    typeof document !== "undefined" && document.documentElement.classList.contains("dark")

  return isDark ? { r: 168, g: 162, b: 158 } : { r: 115, g: 115, b: 115 }
}

export function DotGridBackground({
  className,
  gap = 16,
  dotSize = 1,
  sizeRange = 3,
  opacityRange = 0.72,
  revealRadius = 260,
  seed = defaultSeed,
  rippleActive = false,
  rippleOrigin,
  rippleColor = defaultRippleColor,
  rippleColorAlt = defaultRippleColorAlt,
}: DotGridBackgroundProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const frameRef = useRef<number | null>(null)
  const pointerRef = useRef<{ x: number; y: number } | null>(null)
  const pointerInsideRef = useRef(false)
  const focusWithinRef = useRef(false)
  const activeTargetRef = useRef(0)
  const activeValueRef = useRef(0)
  const lastFrameTimeRef = useRef<number | null>(null)
  const colorRef = useRef(getDotColor())
  const requestDrawRef = useRef<(() => void) | null>(null)
  const warmupFramesRef = useRef(0)
  const rippleTargetRef = useRef(0)
  const rippleValueRef = useRef(0)
  const rippleTravelRef = useRef(0)
  // Track the latest ripple origin/color without re-running the draw effect.
  const rippleOriginRef = useRef(rippleOrigin)
  useEffect(() => {
    rippleOriginRef.current = rippleOrigin
  }, [rippleOrigin])
  const rippleColorRef = useRef(rippleColor)
  useEffect(() => {
    rippleColorRef.current = rippleColor
  }, [rippleColor])
