/* Global website H1: 32/32 on mobile, 40/40 at the tablet breakpoint. Color is
   set per usage so it works on both light surfaces and dark hero imagery. */
.site-h1 {
  font: 500 32px / 32px var(--font-headline);
  letter-spacing: 0;
}

.home-hero-title {
  font: 500 32px / 32px var(--font-headline);
  letter-spacing: 0;
}

.home-globe-stage {
  position: absolute;
  top: -32px;
  left: 50%;
  aspect-ratio: 1;
  width: min(var(--home-globe-size), calc(100vw - 48px));
  .home-agent-cell {
    min-height: 0;
  }

  .home-globe-stage,
  .home-globe-labels {
    top: -40px;
    width: var(--home-globe-size);
  }

  .site-h1 {
    font: 500 40px / 40px var(--font-headline);
  }

  .home-hero-title {
