.docs-sidebar a[aria-current="page"],.docs-sidebar a[aria-current="location"]{
  color:var(--color-text);border-left-color:var(--color-accent);
  background:color-mix(in srgb,var(--color-accent) 8%,transparent)
}
.docs-sidebar .docs-sidebar__subnav{margin:1px 0 10px}
.docs-sidebar .docs-sidebar__subnav a{padding:4px 10px 4px 22px;font-size:12.5px}
.docs-content{min-width:0}
.docs-content > nav[aria-label="On this page"]{display:none}
.documentation-page .docs-content > section > div[style*="grid-template-columns:clamp(64px"]{
  grid-template-columns:minmax(0,1fr)!important
}
.documentation-page .docs-content > section > div[style*="grid-template-columns:clamp(64px"] > [aria-hidden="true"]{
  display:none
}
.documentation-page .docs-content > section:first-child{
  padding-top:clamp(42px,6vw,82px)!important
}
.documentation-page .docs-content > section:first-child h1{
  font-size:clamp(48px,7vw,86px)!important
}

@media (max-width:900px){
  .docs-layout{grid-template-columns:minmax(0,1fr)}
  .docs-sidebar{
    position:sticky;top:57px;z-index:30;max-height:none;margin:0 calc(clamp(16px,3vw,44px) * -1);
    padding:12px clamp(16px,3vw,44px);border-right:0;border-bottom:1px solid var(--rule);
    overflow-x:auto;white-space:nowrap;background:color-mix(in srgb,var(--color-bg) 94%,transparent);
    backdrop-filter:blur(8px)
  }
  .docs-sidebar > .docs-sidebar__title,.docs-sidebar__group,.docs-sidebar__subnav{display:none}
  .docs-sidebar > ul{display:flex;gap:4px}
  .docs-sidebar > ul:last-child{display:none}
  .docs-sidebar > ul > li > a{padding:8px 12px;border-left:0;border-bottom:1px solid transparent}
  .docs-sidebar > ul > li > a[aria-current="page"]{border-bottom-color:var(--color-accent)}
}

@media (max-width:620px){
  .site-header__inner{align-items:center;gap:12px;padding-block:10px}
  .site-nav{order:3;width:100%;justify-content:space-between;gap:10px;margin-left:0}
  .site-header__inner{flex-wrap:wrap}
  .docs-sidebar{top:93px}
  .contribute-page main > nav[aria-label="On this page"]{top:93px!important}
  .home-page main > section > div[style*="grid-template-columns:clamp(64px"],
  .contribute-page main > section > div[style*="grid-template-columns:clamp(64px"],
  .documentation-page .docs-content > section > div[style*="grid-template-columns:clamp(64px"]{
    display:block!important
  }
}

