text(await tools.exec_command({cmd:"cat > /tmp/fix-marvin-mobile.py <<'PY'
from pathlib import Path
import re, html
for p in Path('docs').glob('*.html'):
 s=p.read_text()
 s=re.sub(r'<div style="display:grid;grid-template-columns:clamp\(56px[^\"]*">','<div class="section-heading">',s)
 # Label scrollable tables by their nearest heading without changing their data.
 def table(m):
  before=s[:m.start()]; headings=re.findall(r'<h[123][^>]*>(.*?)</h[123]>',before,re.S)
  label=re.sub('<[^>]+>','',headings[-1]) if headings else 'Reference'
  body=m.group(0)
  head=re.search(r'<thead>(.*?)</thead>',body,re.S)
  columns=len(re.findall(r'<th\b',head.group(1))) if head else 2
  cls='table-scroll table-scroll--wide' if columns>=3 else 'table-scroll'
  return '<div class="'+cls+'" role="region" aria-label="'+html.escape(label,quote=True)+' table" tabindex="0">'+body+'</div>'
 s=re.sub(r'<table\b.*?</table>',table,s,flags=re.S)
 # The wrapper now handles scrolling; remove obsolete surrounding scrollers.
 s=re.sub(r'overflow-x:auto;?(?=[^\"]*">\s*<div class="table-scroll)', '',s)
 if p.name=='electronics.html':
  s=re.sub(r'(<svg viewBox="0 0 940 [^\"]+".*?</svg>)',r'<div class="diagram-scroll" role="region" aria-label="Board architecture diagram" tabindex="0">\1</div>',s,flags=re.S)
 if p.name=='reference.html':
  # The published design-token reference must describe the new design accurately.
  colors={'#f2f2f3':'#f6f6f6','#17181a':'#161616','#1d1f20':'#0f0f0f','#efece6':'#f3f3f3','#5980a6':'#3730a3','#94bce3':'#818cf8','#416180':'#3730a3','#bad4ea':'#a5b4fc'}
  for old,new in colors.items():s=re.sub(re.escape(old),lambda m:new.upper() if m.group().isupper() else new,s,flags=re.I)
  s=s.replace('ink at 14% (hairline) · 34% (section rule)','black at 10% (light) · white at 10% (dark)')
  s=s.replace('Barlow Condensed 600 — numerals, headings, wordmark','Entire Headline — page titles and section headings')
  s=s.replace('Barlow 400/700 — 16px, 1.62 leading, 64–68 character measure','System sans-serif — 16px body text, 24px line height')
  s=s.replace('IBM Plex Mono 400 — pin maps, commands, part numbers, captions','Entire Mono 400/700 — pin maps, commands, part numbers, captions')
  s=s.replace('Six steps: 10.5 · 14.5 · 16 · 19–22 · 28–44 · 56–140','Headlines: 32px mobile, 40px desktop (48px homepage). Sections: 24/28px. Body: 16/24px. Navigation: 14/20px.')
  s=s.replace('a warm near-black ground, warm off-white ink, the steel accent for live state','a neutral near-black ground, off-white ink, the indigo accent for live state')
 p.write_text(s)
p=Path('docs/assets/css/site.css');p.write_text(p.read_text().rstrip()+'\n')
