import { Link, useLocation } from "@tanstack/react-router"
import type { RefObject } from "react"

import {
  isActivePath,
  isSiteNavGroup,
  type SiteNavItem,
  type SiteNavLink,
} from "@/components/nav-data"

interface SiteMobileMenuProps {
  items: SiteNavItem[]
  menuRef: RefObject<HTMLDivElement | null>
  onNavigate: () => void
}

// Group sub-items use the footer's treatment: a muted label that resolves to
// the default color on hover/focus. The current page is shown in `text-default`.
const itemClassName = (active: boolean) =>
  `text-site-footer flex h-8 items-center rounded-lg px-2 font-sans transition-colors hover:text-default focus:outline-2 focus:-outline-offset-2 focus:outline-transparent focus:transition-none focus-visible:outline-focus ${active ? "text-default" : "text-muted"}`
const headingClassName = "text-site-title-sm px-2 font-sans text-default"
// Top-level (non-group) nav items use the heading treatment, but still need
// to branch on `external` so links like Docs open in a new tab instead of
// being handed to TanStack Router as an internal route. The current page
// stays `text-default` and is not dimmed on hover so it reads as active.
const topItemClassName = (active: boolean) =>
  `site-menu-item text-site-title-sm px-2 font-sans text-default transition-colors focus:outline-2 focus:-outline-offset-2 focus:outline-transparent focus:transition-none focus-visible:outline-focus ${active ? "" : "hover:text-muted"}`

function MenuItem({
  item,
  active,
  onNavigate,
}: {
  item: SiteNavLink
  active: boolean
  onNavigate: () => void
}) {
  return item.external ? (
    <a href={item.href} target="_blank" rel="noopener noreferrer" className={itemClassName(false)}>
      {item.label}
    </a>
  ) : (
    <Link to={item.href} className={itemClassName(active)} onClick={onNavigate}>
      {item.label}
    </Link>
  )
}

/**
 * Fullscreen mobile navigation. Renders below the (sticky, while open) header as
 * a flat list of sections — each group is a heading followed by a two-column
 * grid of links — mirroring the footer's typography and hover treatment.
 */
export function SiteMobileMenu({ items, menuRef, onNavigate }: SiteMobileMenuProps) {
  const location = useLocation()
  return (
    <div
      id="site-mobile-menu"
      ref={menuRef}
      className="fixed inset-x-0 top-16 bottom-0 z-40 overflow-y-auto bg-(--surface-base) px-4 py-5 md:hidden"
      role="dialog"
      aria-label="Main menu"
      aria-modal="true"
      tabIndex={-1}
    >
      <nav className="flex flex-col gap-8">
        {items.map((item, index) => {
          const animationStyle = { animationDelay: `${index * 60}ms` }
          return isSiteNavGroup(item) ? (
            <section
              key={item.label}
              className="site-menu-item flex flex-col gap-3"
              style={animationStyle}
            >
              <h2 className={headingClassName}>{item.label}</h2>
              <div className="grid grid-cols-2 gap-0.5">
                {item.items.map((subItem) => (
                  <MenuItem
                    key={subItem.href}
                    item={subItem}
                    active={isActivePath(location.pathname, subItem.href)}
                    onNavigate={onNavigate}
                  />
                ))}
              </div>
            </section>
          ) : item.external ? (
            <a
              key={item.href}
              href={item.href}
              target="_blank"
              rel="noopener noreferrer"
              style={animationStyle}
              className={topItemClassName(false)}
            >
              {item.label}
            </a>
          ) : (
            <Link
              key={item.href}
              to={item.href}
              onClick={onNavigate}
              style={animationStyle}
              className={topItemClassName(isActivePath(location.pathname, item.href))}
            >
              {item.label}
            </Link>
          )
        })}
      </nav>
    </div>
  )
}

